package com.rustybank.legacy;

import com.rustybank.TellerTerminal;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class LegacyTellerTerminal implements TellerTerminal {

    private final Map<String, BigDecimal> accounts = new HashMap<>();

    public LegacyTellerTerminal(AccountStore store) {
        // This terminal keeps its own exact-balance ledger.
    }

    @Override
    public void openAccount(String accountId) {
        if (accountId == null || accountId.trim().length() == 0) {
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        }
        if (accounts.containsKey(accountId)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + accountId);
        }
        accounts.put(accountId, BigDecimal.ZERO.setScale(2));
    }

    @Override
    public void deposit(String accountId, String amount) {
        BigDecimal balance = accounts.get(accountId);
        if (balance == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + accountId);
        }
        BigDecimal value = parseCents(amount);
        accounts.put(accountId, balance.add(value));
    }

    @Override
    public void withdraw(String accountId, String amount) {
        BigDecimal balance = accounts.get(accountId);
        if (balance == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + accountId);
        }
        BigDecimal value = parseCents(amount);
        if (value.compareTo(balance) > 0) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }
        accounts.put(accountId, balance.subtract(value));
    }

    @Override
    public String balance(String accountId) {
        BigDecimal balance = accounts.get(accountId);
        if (balance == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + accountId);
        }
        return format(balance);
    }

    @Override
    public String postMonthlyInterest(String accountId, String annualRatePercent) {
        BigDecimal balance = accounts.get(accountId);
        if (balance == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + accountId);
        }
        BigDecimal rate = parseRate(annualRatePercent);
        BigDecimal interest = balance.multiply(rate)
                .divide(BigDecimal.valueOf(1200), 2, RoundingMode.HALF_UP);
        BigDecimal newBalance = balance.add(interest);
        accounts.put(accountId, newBalance);
        return format(interest);
    }

    @Override
    public List<String> splitPayment(String fromAccountId, String amount, List<String> payeeIds) {
        BigDecimal fromBalance = accounts.get(fromAccountId);
        if (fromBalance == null) {
            throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + fromAccountId);
        }
        if (payeeIds == null || payeeIds.size() == 0) {
            throw new IllegalArgumentException("NO PAYEES");
        }

        List<String> payees = new ArrayList<>(payeeIds);
        for (String payeeId : payees) {
            if (accounts.get(payeeId) == null) {
                throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + payeeId);
            }
        }

        BigDecimal total = parseCents(amount);
        if (total.compareTo(fromBalance) > 0) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }

        BigInteger totalCents = total.movePointRight(2).toBigIntegerExact();
        BigInteger payeesValue = BigInteger.valueOf(payees.size());
        BigInteger baseCents = totalCents.divide(payeesValue);
        BigInteger remainderCents = totalCents.mod(payeesValue);

        List<String> shares = new ArrayList<>();
        for (int i = 0; i < payees.size(); i++) {
            BigInteger cents = baseCents;
            if (BigInteger.valueOf(i).compareTo(remainderCents) < 0) {
                cents = cents.add(BigInteger.ONE);
            }
            BigDecimal share = new BigDecimal(cents).movePointLeft(2);
            shares.add(format(share));
            accounts.put(payees.get(i), accounts.get(payees.get(i)).add(share));
        }

        accounts.put(fromAccountId, fromBalance.subtract(total));
        return shares;
    }

    @Override
    public String totalHoldings() {
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        for (BigDecimal balance : accounts.values()) {
            sum = sum.add(balance);
        }
        return format(sum);
    }

    private static BigDecimal parseCents(String amount) {
        if (amount == null) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
        String cleaned = amount.trim();
        if (cleaned.isEmpty()) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
        BigDecimal value;
        try {
            value = new BigDecimal(cleaned);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
        if (value.signum() <= 0) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
        return value.setScale(2, RoundingMode.HALF_UP);
    }

    private static BigDecimal parseRate(String rate) {
        if (rate == null) {
            throw new IllegalArgumentException("INVALID RATE");
        }
        String cleaned = rate.trim();
        if (cleaned.isEmpty()) {
            throw new IllegalArgumentException("INVALID RATE");
        }
        BigDecimal value;
        try {
            value = new BigDecimal(cleaned);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("INVALID RATE");
        }
        if (value.signum() < 0) {
            throw new IllegalArgumentException("INVALID RATE");
        }
        return value;
    }

    private static String format(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
        return amount.setScale(2, RoundingMode.HALF_UP).toPlainString();
    }
}
